#include "local_propagation_channels.hpp"
namespace hanmo::resident {
const PropagationChannelRead*NativeLocalPropagationRead::owner(MessageChannelKind k)const noexcept{if(!face_.bound_to(common_,social_)||!custody_.bound_to(common_,social_))return nullptr;switch(k){case MessageChannelKind::face_to_face:return &face_;case MessageChannelKind::custodian_pickup:return &custody_;case MessageChannelKind::carrier_delivery:return carrier_&&carrier_->bound_to(common_,social_)&&carrier_->supports(k)?carrier_:nullptr;default:return nullptr;}}
bool NativeLocalPropagationRead::supports(MessageChannelKind k)const noexcept{return owner(k)!=nullptr;}
bool NativeLocalPropagationRead::supports_report(KnowledgeCategory k)const noexcept{return face_.supports_report(k)&&custody_.supports_report(k)&&(!carrier_||carrier_->supports_report(k));}
Outcome<PropagationRecipientPage>NativeLocalPropagationRead::known_recipients(const SubjectRef&s,Integer cursor,Integer limit,const ReadStamp&stamp)const{if(!owner(MessageChannelKind::face_to_face))return {false,{},common_failure("PropagationOwnerCandidateMismatch").error};return face_.known_recipients(s,cursor,limit,stamp);}
Outcome<std::optional<PropagationChannelProposal>>NativeLocalPropagationRead::prepare(const SubjectRef&s,const Report&r,const PropagationRecipient&recipient,MessageChannelKind k,const ReadStamp&stamp)const{const auto*p=owner(k);return p?p->prepare(s,r,recipient,k,stamp):Outcome<std::optional<PropagationChannelProposal>>{false,{},common_failure("OriginalPropagationChannelRequired",{},ErrorKind::unsupported_capability).error};}
Outcome<PropagationActualDispatch>NativeLocalPropagationRead::read_actual_dispatch(const StableId&id)const{const auto*m=social_.dynamic?social_.dynamic->pending_messages.find(id):nullptr;if(!m)return {false,{},common_failure("ActualPropagationMessageMissing",id).error};auto k=read_message_channel_kind(m->channel);if(!k.ok)return {false,{},k.error};const auto*p=owner(k.value);return p?p->read_actual_dispatch(id):Outcome<PropagationActualDispatch>{false,{},common_failure("OriginalPropagationChannelRequired",id,ErrorKind::unsupported_capability).error};}
Status NativeLocalPropagationRead::validate_known_recipient_at_cut(const SubjectRef&s,const SubjectRef&r,const OriginalSocialRelationCut&cut)const{if(!owner(MessageChannelKind::face_to_face))return common_failure("PropagationOwnerCandidateMismatch",s.id,ErrorKind::internal);return face_.validate_known_recipient_at_cut(s,r,cut);}
Status NativeLocalPropagationRead::validate_actual_dispatch_after_cut(const PropagationActualDispatch&a,const OriginalSocialRelationCut&cut)const{const auto*p=owner(a.channel);return p?p->validate_actual_dispatch_after_cut(a,cut):common_failure("OriginalPropagationChannelRequired",a.message_id,ErrorKind::unsupported_capability);}
Status NativeLocalPropagationRead::validate_historical_disclosure(const SocialPropagationDecision&d,const PropagationActualDispatch&a)const{const auto*p=owner(a.channel);return p?p->validate_historical_disclosure(d,a):common_failure("OriginalPropagationChannelRequired",a.message_id,ErrorKind::unsupported_capability);}
Outcome<StableId>NativeLocalPropagationWrite::adopt(const PropagationChannelProposal&p,const SubjectRef&s,const StableId&r,const ReadStamp&stamp){switch(p.channel){case MessageChannelKind::face_to_face:return face_.adopt(p,s,r,stamp);case MessageChannelKind::custodian_pickup:return custody_.adopt(p,s,r,stamp);case MessageChannelKind::carrier_delivery:if(carrier_)return carrier_->adopt(p,s,r,stamp);[[fallthrough]];default:return {false,{},common_failure("OriginalPropagationChannelRequired",{},ErrorKind::unsupported_capability).error};}}
}
